use vstd::prelude::*;

verus! {

fn ones_like<T>(a: &Vec<T>) -> (result: Vec<i32>)
    ensures
        // The result has the same length as the input
        result.len() == a.len(),
        // Every element of the result is 1
        forall |i: usize| i < result.len() ==> result[i] == 1,
{
    let mut result: Vec<i32> = Vec::new();
    let n: usize = a.len();
    let mut idx: usize = 0;

    // Build `result` by pushing 1's, one per input element.
    while idx < n
        invariant
            // The loop counter stays within bounds
            idx <= n,
            // The current length of `result` equals the number of iterations done
            result.len() == idx,
            // All elements so far are 1
            forall |j: usize| j < result.len() ==> result[j] == 1,
        decreases n - idx,
    {
        result.push(1);
        idx = idx + 1;
    }

    result
}

} // end of verus! 

